#include "../../server/slicing/SwgxrSlicingPuzzle.h"
#include <cassert>
#include <iostream>
int main(){using namespace SwgxrSlicingPuzzle;int count=0,complete=0,alternate=0;for(int size=3;size<=5;++size)for(int colors=2;colors<=4;++colors)for(unsigned int seed=0;seed<1000;++seed){auto b=generate(size,colors,seed);assert(validate(b,b.witness));int filled=0;for(auto&w:b.preconnected){auto& expected=b.witness[w.color];if(w.cells.back()==expected.cells.back()){++complete;++filled;if(w.cells!=expected.cells)++alternate;}}assert(filled<colors);std::set<int> initial;for(auto&w:b.preconnected)for(auto&c:w.cells)assert(initial.insert(index(c,size)).second);auto broken=b.witness;broken[0].cells.pop_back();assert(!validate(b,broken));broken=b.witness;broken[0].cells[1]=broken[1].cells[0];assert(!validate(b,broken));broken=b.witness;broken[0].cells[1][0]=size;assert(!validate(b,broken));broken=b.witness;broken[0].cells.erase(broken[0].cells.begin()+1);assert(!validate(b,broken));broken=b.witness;broken[1].color=broken[0].color;assert(!validate(b,broken));broken=b.witness;std::reverse(broken[0].cells.begin(),broken[0].cells.end());assert(validate(b,broken));++count;}assert(complete>0 && alternate>0);std::cout<<complete<<" full preconnections, "<<alternate<<" alternative full routes; "<<count<<" native puzzles: all witnesses solvable, preconnections disjoint; invalid endpoints/overlap/bounds/adjacency/colors rejected; reversed paths accepted\n";}
